// Vite配置
// vite.config.js
import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';
import path from 'path';

export default defineConfig({
  plugins: [react()],
  resolve: {
    alias: { '@': path.resolve(__dirname, 'src') }
  },
  server: {
    port: 3000,
    proxy: {
      '/api': {
        target: 'http://localhost:8080',
        changeOrigin: true
      }
    }
  },
  build: {
    rollupOptions: {
      output: {
        manualChunks: {
          vendor: ['react', 'react-dom'],
          utils: ['lodash-es']
        }
      }
    },
    chunkSizeWarningLimit: 1000
  }
});

// Vite插件示例（简单的版本注入）
export function versionPlugin() {
  return {
    name: 'version-plugin',
    transformIndexHtml(html) {
      return html.replace(
        '</head>',
        `<meta name="version" content="${process.env.npm_package_version}" /></head>`
      );
    }
  };
}

// import.meta.url 热更新
if (import.meta.hot) {
  import.meta.hot.accept('./module', (newModule) => {
    // 模块更新时的处理
  });
}

// 环境变量
// .env                所有环境
// .env.development    开发环境
// .env.production     生产环境

// VITE_API_URL=http://localhost:8080
console.log(import.meta.env.VITE_API_URL); // 只有VITE_前缀的变量会暴露

// Vite vs Webpack选型
// 选Vite：
// - 新项目、Vue/React项目
// - 开发体验优先
// - 中小规模项目

// 选Webpack：
// - 需要复杂定制的大型项目
// - 遗留项目迁移成本高
// - 需要特定Webpack插件生态
